/**
 * **The Discovery conduct block is PINNED in `context.md` and never trimmed.**
 * (2026-08-22, the author's Discovery Conduct brief, item 8.)
 *
 * `context.md` is generated by `pnpm handoff` under a 40 KB cap, and it shrinks
 * to fit by dropping tracker-change rows and clipping P0 notes. This asserts
 * that the shrink cascade **never reaches the pinned block** — including at a
 * cap far below anything the real file will ever run at, which is the only way
 * to prove an exemption rather than observe that it happened not to be needed.
 *
 * ## Why a pinned block at all, when everything else here is an index
 *
 * Every other section is headings, counts and pointers, on the principle that a
 * session needing the text reads the file. That is right, and it is exactly
 * wrong here: the failure RULING 88 exists to fix is a session **not knowing
 * there was anything to look up**. A pointer reads as *more rules about hunting,
 * consult if stuck*, which is how the three previous fixes were absorbed and
 * then not applied.
 */
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";

import { buildContext, CAP_BYTES } from "../scripts/context-file.mjs";

const ROOT = process.cwd();

const OPTIONS = {
  gitFacts: [],
  generatedAt: "test",
  stampToday: "2026-08-23",
};

test("context.md carries the Discovery conduct block verbatim from CLAUDE.md", async () => {
  const built = await buildContext(OPTIONS);
  const law = readFileSync(join(ROOT, "CLAUDE.md"), "utf8");

  const start = law.indexOf("## DISCOVERY CONDUCT");
  assert.notEqual(start, -1, "CLAUDE.md has no `## DISCOVERY CONDUCT` section");

  // Verbatim, not paraphrased: a distinctive run of the law's own text must
  // appear in the generated file unchanged.
  for (const clause of [
    "## DISCOVERY CONDUCT",
    "### RULING 88 — THE EXPANSION REQUIREMENT",
    "### RULING 89 — EXPANSION IS NOT A SIDE QUEST",
    "### RULING 94 — THE STUCK PROTOCOL",
    "### RULING 95 — CREDENTIALS ARE PROVEN, NOT ASSUMED",
    "### RULING 96 — SOURCES HAVE FRESHNESS",
    "### RULING 97 — A FOUNDER FIND IS A CLASS-WIDE DEFECT",
    "### RULING 98 — EXPLORATION HOLDS A GUARANTEED POSITION IN ITEM ORDER",
    "### RULING 99 — THE AMENDMENT PROCEDURE",
    // The clause most likely to be lost, and the one the whole rule turns on.
    // Matched as a single line: the law wraps it mid-sentence.
    "The invention is the deliverable, not the yield.",
  ]) {
    assert.ok(law.includes(clause), `CLAUDE.md no longer contains ${JSON.stringify(clause)}`);
    assert.ok(built.text.includes(clause), `context.md dropped ${JSON.stringify(clause)}`);
  }
});

test("the shrink cascade never reaches the pinned block, even at a punishing cap", async () => {
  // Well below anything the real file runs at. If the block survives here it
  // survives anywhere, and an exemption that has never been exercised is an
  // exemption nobody has actually tested.
  const built = await buildContext({ ...OPTIONS, cap: 16 * 1024 });

  assert.ok(built.text.includes("## DISCOVERY CONDUCT"), "the pinned block was trimmed away");
  assert.ok(built.text.includes("### RULING 88 — THE EXPANSION REQUIREMENT"), "RULING 88 was trimmed away");
  assert.ok(built.text.includes("### RULING 99 — THE AMENDMENT PROCEDURE"), "RULING 99 was trimmed away");

  // And the file is honest about being over: a silent overrun is the same
  // defect as a silent truncation, pointing the other way.
  assert.equal(built.truncated, true);
  assert.ok(
    built.truncation.some((t: string) => t.includes("STILL OVER")),
    `at a 16 KB cap the file must SAY it is over the cap; truncation was ${JSON.stringify(built.truncation)}`,
  );
});

test("what the pinned block costs is stated, not silent", async () => {
  const built = await buildContext(OPTIONS);
  // At the real cap the block is affordable but not free. Whatever gave way
  // must be named in the file itself — never dropped quietly.
  if (built.truncated) {
    assert.ok(
      built.truncation.length > 0,
      "the build reports truncated:true with nothing named as trimmed",
    );
    assert.match(
      built.text,
      /Truncated to fit the \d+ KB cap/,
      "the generated file does not say, in its own text, that it was truncated",
    );
  }
  assert.ok(built.bytes > 0);
  assert.ok(CAP_BYTES === 40 * 1024, "the cap moved — re-read the trade this test documents");
});
